  ('t3_34940', '2. Eroberung der Scheune', '2024-06-08', '2024-06-08', 30, 'Germany', 'Bedburg', 50181, 'Meisenweg 1', 'Wir laden euch zu unserem 2. Turnier von Conquest - The Last Argument of Kings ein! Es werden 3 Runden mit einer 2000 Punkte-Liste gespielt. Venue: Clubräume der Bedburger Tabletopfreunde e.V..', 'https://www.tabletopturniere.de/t3_tournament.php?tid=34940', '20838880c6cff6c098736c039ffb87ea910888d99f7f9fb82a1bee017f36ed74', 'ended', 3, 'ended', '2024-06-08 00:00:00'),
  ('t3_34963', '4. Badisch Conquest', '2024-07-06', '2024-07-06', 24, 'Germany', 'March', 79232, 'Sportplatzstraße 20', 'Gespielt werden 3 Runden mit 2000 Punkte nach dem aktuellen Regelwerk. Es gibt offiziellen Preissupport von Para Bellum und vor allem viel Spaß und gute Laune an den Tag. - - - - Played are 3 rounds with 2000 points according to the current rulebook. Ther', 'https://www.tabletopturniere.de/t3_tournament.php?tid=34963', '902ad9350e868c17d1b9d31ca3ede5aa838af032ae8bae9245daeb061c2bfbde', 'ended', 3, 'ended', '2024-07-06 00:00:00'),
  ('t3_33710', '2. Kelpie Con Conquest Turnier', '2024-10-26', '2024-10-26', 16, 'Germany', 'Bremerhaven', 27570, 'Rheinstraße 109', '2000 Punkte Spiel, Spaß und Spannung Venue: Haus der Jugend.', 'https://www.tabletopturniere.de/t3_tournament.php?tid=33710', '25c8e38afbf3dd70c974adef2954e74999e39655eafca1a14060e15c46cf7601', 'ended', 3, 'ended', '2024-10-26 00:00:00'),
