  ('t3_35935', '1. Drunken Conquest – Last Argument of Dwarfs', '2025-02-01', '2025-02-01', 32, 'Germany', 'Duisburg', 47229, 'Am Borgschenhof 8', 'Wir laden euch zu unserem 1. Turnier von Conquest - The Last Argument of Kings im Zwergenbunker ein! Es werden 3 Runden mit einer 2000 Punkte-Liste gespielt. We invite you to our first tournament of Conquest - The Last Argument of Kings at the Zwergenbunk', 'https://www.tabletopturniere.de/t3_tournament.php?tid=35935', '4920ae34d829b37bafa56441aea6f2a3fe382da76832c5cb60b73332260a7fde', 'ended', 3, 'ended', '2025-02-01 00:00:00'),
  ('t3_37528', '2. Schwaben Conquest', '2025-05-25', '2025-05-25', 18, 'Germany', 'Wolfschlugen', 72649, 'Benzstr. 18', 'Wir spielen ein entspanntes 2000-Punkte-Turnier mit 3 Runden. Venue: Schwäbischer Albverein e.V. Ortsgruppe Wolfschlugen.', 'https://www.tabletopturniere.de/t3_tournament.php?tid=37528', '63dbccf23a2bbf565888ffee5633913e47d9bf0ff4ceccc83261c4fa9f97de3b', 'ended', 3, 'ended', '2025-05-25 00:00:00'),
