  ('t3_35942', '2. Drunken Conquest – Last Argument of Dwarfs', '2026-03-14', '2026-03-14', 40, 'Germany', 'Duisburg', 47229, 'Am Borgschenhof 8', 'Wir laden euch zu unserem 2. Turnier von Conquest - The Last Argument of Kings im Zwergenbunker ein! Es werden 3 Runden mit einer 2000 Punkte-Liste gespielt. We invite you to our second tournament of Conquest - The Last Argument of Kings at the Zwergenbun', 'https://www.tabletopturniere.de/t3_tournament.php?tid=35942', '4920ae34d829b37bafa56441aea6f2a3fe382da76832c5cb60b73332260a7fde', 'ended', 3, 'ended', '2026-03-14 00:00:00'),
